steps.script:
GameState.state["factions"]["1"].merge({"detachment": "Kult of Speed"}, true)
StratagemManager.load_faction_stratagems_for_player(1)
var u = GameState.state.units
var tb: Array = u["U_TANKBUSTAS_A"].models
for i in range(tb.size()):
	tb[i]["position"] = {"x": (21.5 + i * 1.6) * 40.0, "y": 1.2 * 40.0}
tb[0]["current_wounds"] = 1
tb[1]["current_wounds"] = 1
var ko: Array = u["U_KOMMANDOS_A"].models
for i in range(ko.size()):
	ko[i]["position"] = {"x": (19.0 + i * 1.3) * 40.0, "y": 9.3 * 40.0}
ko[0]["alive"] = false
ko[0]["current_wounds"] = 0
ko[1]["alive"] = false
ko[1]["current_wounds"] = 0
u["U_BREAKA_BOYZ_A"].models[0]["current_wounds"] = 1
tree.current_scene._recreate_unit_visuals()
var M = load("res://scripts/stratagems/ork_codex/OrkCodexMovement.gd")
return M.delicious_squigs_targets("U_RUKKATRUKK_SQUIGBUGGIES_A", 1)

var d = tree.root.get_node("StratagemTargetDialog")
var t = d.get_node("Content/Pick_U_RUKKATRUKK_SQUIGBUGGIES_A").text
return [d.title, d.get_node("Content/Prompt").text.contains("within 3\" of it heals 3 wounds"), t.contains("heals "), t.contains("Tankbustas"), t.contains("Kommandos"), t.contains("Breaka")]
